// Raw exposes the underlying DML entity for direct attribute
// manipulation within the same entity frame. The type lives in
// internal/lowlevel: callers outside the generated package hold the
// returned value by inference (raw := b.Raw()) and chain its
// methods, but cannot name the type in their own signatures.
func (inst *JobEntityBuilder) Raw() *lowlevel.InEntityWatchbillTable {
	if err := inst.buf.MarkRaw(); err != nil {
		inst.store.dml.AppendError(err)
	}
	inst.raw = true // direct DML writes cannot be mirrored into the entity
	return inst.store.dml
}

// Commit finishes the open entity, buffers the row, and writes it
// through to attached cache views: the entity is populated and pinned
// until the store's Flush makes it durable — reads after writes hit
// immediately, and the caching version gate plus the pin make a raced
// refetch of the pre-write row bounce off. A commit that touched
// Raw() cannot be materialized faithfully and invalidates the key
// instead. A failed Commit rolls the frame back — the entity is
// discarded and the store stays usable.
func (inst *JobEntityBuilder) Commit() (err error) {
	if ferr := inst.buf.Flush(inst.endSection); ferr != nil {
		inst.store.dml.AppendError(ferr) // surfaced by CommitEntity below
	}
	inst.buf.Reset()
	err = lowlevel.InEntityWatchbillTableCommitEntity(inst.store.dml)
	inst.store.dml.PopMembershipsHighCardRef(inst.pushed) // release Begin's ambient stamps (consumed by the closed attributes)
	if err != nil {
		_ = lowlevel.InEntityWatchbillTableRollbackEntity(inst.store.dml) // no-op error when no frame is open
		return
	}
	inst.store.buffered++
	inst.store.dirty[inst.key] = struct{}{}
	if inst.raw {
		inst.store.notifyWrite(inst.key, nil)
	} else {
		ent := inst.ent
		inst.store.notifyWrite(inst.key, &ent)
	}
	return
}

// Rollback abandons the open entity frame without committing it;
// already-buffered rows and the store remain usable.
func (inst *JobEntityBuilder) Rollback() (err error) {
	inst.buf.Reset() // the buffered contributions are abandoned with the frame
	inst.store.dml.PopMembershipsHighCardRef(inst.pushed)
	return lowlevel.InEntityWatchbillTableRollbackEntity(inst.store.dml)
}

// IngestJob buffers one whole entity per row carrying only the
// Job component, all stamped with ts — rows ship on the next Flush,
// like every write. Keys must be distinct within one call (rows
// share ts, so duplicates would tie on Order): a duplicate returns
// recordstore.ErrDuplicateIngestKey. On any error the rows buffered
// so far remain buffered — Flush ships them, DiscardPending drops
// them.
func (inst *JobStore) IngestJob(ts time.Time, rows []Job) (err error) {
	seen := make(map[string]struct{}, len(rows))
	for i := range rows {
		if _, dup := seen[rows[i].ID]; dup {
			err = eh.Errorf("ingest job row %d: %w: key %v", i, recordstore.ErrDuplicateIngestKey, rows[i].ID)
			return
		}
		seen[rows[i].ID] = struct{}{}
		err = inst.Begin(rows[i].ID, ts).AddJob(rows[i]).Commit()
		if err != nil {
			err = eh.Errorf("ingest job row %d: %w", i, err)
			return
		}
	}
	return
}

// Buffered reports the number of committed-but-unflushed rows.
func (inst *JobStore) Buffered() int { return inst.buffered }

// Flush drains the buffered rows to ClickHouse (Arrow IPC, ADR-0089
// pivot). Rows are durable when Flush returns, engine permitting. On
// insert failure the transferred records are retained and the next
// Flush ships them — Flush is retryable; DiscardPending drops them
// instead. An open (uncommitted) entity frame makes Flush error.
func (inst *JobStore) Flush(ctx context.Context) (n int, err error) {
	// Ordered flush (ADR-0112 SD5): make the dimension facts this batch
	// references durable before the payload insert, so a referencing row is
	// never durable ahead of its descriptor. On failure nothing is
	// transferred yet — the buffered rows stay and the next Flush retries.
	//
	// This runs BEFORE the nothing-to-do return: a Begin that stamped and
	// then rolled back, or a caller flushing a store whose own rows all
	// went elsewhere, still leaves dimension rows buffered in the stampers,
	// and skipping them here would strand descriptors no later Flush of
	// this store is obliged to ship. Flushing an empty stamper is free.
	if !inst.cfg.BestEffortStampFlush {
		for _, s := range inst.stampers {
			if _, ferr := s.Flush(ctx); ferr != nil {
				err = eh.Errorf("ordered flush of stampers: %w", ferr)
				return
			}
		}
	}
	if inst.buffered == 0 && len(inst.pending) == 0 {
		return
	}
	records, err := lowlevel.InEntityWatchbillTableTransferRecords(inst.dml, nil)
	if err != nil {
		err = eh.Errorf("transfer records: %w", err)
		return
	}
	records = append(inst.pending, records...)
	inst.pending = nil
	if len(records) > 0 {
		err = inst.exec.InsertArrow(ctx, inst.tableName(), records)
		if err != nil {
			inst.pending = records
			err = eh.Errorf("insert into %s: %w", inst.tableName(), err)
			return
		}
	}
	for _, rec := range records {
		rec.Release()
	}
	n = inst.buffered
	inst.buffered = 0
	for k := range inst.dirty {
		inst.notifyFlush(k) // durable now — release the views' dirty-window pins
	}
	clear(inst.dirty) // flushed — ClickHouse now serves the written state
	return
}

// DiscardPending drops every committed-but-unflushed row: records
// retained by a failed Flush, rows still in the DML builder, and an
// open (uncommitted) entity frame. It gives a failed Flush "never
// happened" semantics — ClickHouse state is the truth afterwards.
// Ambient stamps are cleared with the frame they were pushed for —
// including any pushed through Raw() — so an abandoned builder cannot
// leak its stamps onto later entities.
func (inst *JobStore) DiscardPending() {
	_ = lowlevel.InEntityWatchbillTableRollbackEntity(inst.dml) // no-op error when no frame is open
	inst.dml.ClearMembershipsHighCardRef()                      // an abandoned Begin's stamps must not outlive its frame
	if records, err := lowlevel.InEntityWatchbillTableTransferRecords(inst.dml, nil); err == nil {
		for _, rec := range records {
			rec.Release()
		}
	}
	for _, rec := range inst.pending {
		rec.Release()
	}
	inst.pending = nil
	inst.buffered = 0
	for k := range inst.dirty {
		inst.notifyWrite(k, nil) // the cached write never became durable — invalidate
	}
	clear(inst.dirty) // nothing local remains — ClickHouse is the truth
}

// Close discards everything unflushed and releases the store's Arrow
// builder; the store must not be used afterwards. Required for a
// clean shutdown under tracking/checked allocators — the default Go
// allocator needs no Close.
func (inst *JobStore) Close() {
	inst.DiscardPending()
	lowlevel.InEntityWatchbillTableReleaseBuilder(inst.dml)
}

// JobCacheConfig parameterizes an attached read-through cache view.
type JobCacheConfig struct {
	// Capacity is the L1 capacity in entries, not bytes — budget
	// memory as Capacity × the largest expected entity payload. Zero
	// or negative selects the default (1024).
	Capacity int
	// FetchCriteria are the cache's batch-flush thresholds.
	FetchCriteria caching.FetchCriteria
	// FreshnessTTL enables age-based staleness onset (ADR-0100's
	// external-writer staleness story): entries older than this read
	// as stale — strict reads miss and queue a refetch, accept-stale
	// reads keep serving. Zero disables (staleness stays signal-only).
	FreshnessTTL time.Duration
	// NegativeTTL enables absent-key marking: keys a clean fetch did
	// not return are treated as absent for this long — misses on them
	// neither queue nor suspend work items, so replay loops over keys
	// that do not exist terminate. Zero disables.
	NegativeTTL time.Duration
}

// JobCache is the batched read-through, write-through KV view over a
// JobStore (ADR-0100 SD5): misses queue under work items and flush
// as one IN (…) lookup, and local writes populate the view at Commit —
// pinned until the store's Flush makes them durable — so reads after
// writes hit immediately. Admission is version-gated on the entity's
// Order timestamp: a raced refetch of an older row bounces off. Only
// EXTERNAL writers can leave the view stale; they need a caller-
// provided signal: MarkStale / Invalidate / InvalidateAll (a freshness
// TTL option exists on the underlying cache). Raw() commits and
// discarded writes invalidate instead of populating. Like the store
// it wraps, a view is single-goroutine. W is the work-item type (use
// struct{} when the suspend/replay machinery is not needed).
type JobCache[W comparable] struct {
	st    *JobStore
	cfg   JobCacheConfig
	cache *caching.ReadThroughCache[string, *JobEntity, W]
}

// NewJobCache attaches a read-through, write-through cache view to st,
// registering its write-through and flush hooks with the store. Views
// attach for the store's lifetime — there is no detach.
func NewJobCache[W comparable](st *JobStore, cfg JobCacheConfig) (inst *JobCache[W]) {
	if cfg.Capacity <= 0 {
		cfg.Capacity = 1024
	}
	inst = &JobCache[W]{st: st, cfg: cfg}
	inst.rebuild()
	// The hooks close over the view, not the cache instance, keeping
	// them correct if the cache is ever swapped out.
	st.onWrite = append(st.onWrite, func(k string, ent *JobEntity) {
		if ent == nil {
			inst.cache.Delete(k) // not materializable or discarded: invalidate
			return
		}
		inst.cache.AddItem(k, ent) // version-gated write-through
		inst.cache.Pin(k)          // dirty-window latch, released by Flush
	})
	st.onFlush = append(st.onFlush, func(k string) { inst.cache.Unpin(k) })
	return
}

func (inst *JobCache[W]) rebuild() {
	opts := []caching.CacheOption[string, *JobEntity, W]{
		// Admission mirrors the table's newest-row-per-key semantics:
		// the Order timestamp is the entity's monotonic version.
		caching.WithVersioning[string, *JobEntity, W](func(e *JobEntity) int64 { return e.Ts.UnixNano() }),
	}
	if inst.cfg.FreshnessTTL > 0 {
		opts = append(opts, caching.WithFreshnessTTL[string, *JobEntity, W](inst.cfg.FreshnessTTL))
	}
	if inst.cfg.NegativeTTL > 0 {
		opts = append(opts, caching.WithNegativeCaching[string, *JobEntity, W](inst.cfg.NegativeTTL))
	}
	inst.cache = caching.NewReadThroughCache[string, *JobEntity, W](inst.cfg.Capacity, &watchbillFetcher{st: inst.st}, inst.cfg.FetchCriteria, opts...)
}

// Get retrieves an entity by Key through the cache; local writes are
// visible immediately (write-through). A miss queues the key for the
// next batch fetch (the caching suspend/replay contract). A miss can
// also mean the batched fetch errored (misses swallow fetch errors;
// the circuit breaker backs off) — GetFetch surfaces the error
// instead, and the store's Latest stays the authoritative check. The
// returned entity is shared with the cache: treat it as immutable.
func (inst *JobCache[W]) Get(key string) (ent *JobEntity, found bool) {
	return inst.cache.Get(key)
}

// GetFetch is the single-lookup read: the cached entity when present,
// otherwise one immediate batched point fetch — fetch errors surface
// instead of reading as misses, so found=false with err=nil is the
// authoritative absent. A key in the dirty write window that the cache
// could not answer is an error rather than a stale row (see below).
// Prefer Get plus the work-item protocol when batching lookups across a
// frame; the initial miss here also queues the key, so a later batch
// fetch may include it redundantly (harmless).
func (inst *JobCache[W]) GetFetch(ctx context.Context, key string) (ent *JobEntity, found bool, err error) {
	ent, found = inst.cache.Get(key)
	if found {
		return
	}
	if _, d := inst.st.dirty[key]; d {
		// The key was written locally and is not yet flushed, so ClickHouse
		// still serves the PRE-write row — and the cache miss above means
		// there is no local answer either (a Raw() commit, or a discarded
		// write, invalidates the entry rather than materializing it; an
		// ordinary commit is pinned and would have hit). Returning the
		// pre-write row would be stale, and found=false would assert the
		// authoritative absent this method promises and cannot stand behind
		// here — so say so instead. Flush first, or read through Get plus the
		// work-item protocol, whose fetcher drops dirty keys as a MISS, which
		// queues a refetch rather than claiming absence.
		err = eh.Errorf("get-fetch: key is in the dirty write window — written locally and not yet flushed, and the write was not materializable into the cache; Flush before reading it back")
		return
	}
	ents, err := inst.st.queryEntities(ctx, inst.st.fetchLatestSQL([]string{key}))
	if err != nil {
		err = eh.Errorf("get-fetch: %w", err)
		return
	}
	for _, e := range ents {
		if e.ID != key {
			continue
		}
		ent = e
		found = true
		inst.cache.AddItem(key, e)
	}
	return
}

// WorkItem marks the current work item for the cache's miss bookkeeping.
func (inst *JobCache[W]) WorkItem(w W) iter.Seq[functional.NilIteratorValueType] {
	return inst.cache.WorkItem(w)
}

// IterateReadyWorkItems flushes the queued keys when the fetch criteria
// are met and replays the work items that had misses.
func (inst *JobCache[W]) IterateReadyWorkItems(ctx context.Context) iter.Seq[W] {
	return inst.cache.IterateReadyWorkItems(ctx)
}

// IterateRestWorkItems forces a fetch of all queued keys and replays
// the pending work items.
func (inst *JobCache[W]) IterateRestWorkItems(ctx context.Context) iter.Seq[W] {
	return inst.cache.IterateRestWorkItems(ctx)
}

// AdvanceEpoch advances the cache's pinning epoch — call once per
// frame / batch so untouched L1 entries become evictable.
func (inst *JobCache[W]) AdvanceEpoch() {
	inst.cache.AdvanceEpoch()
}

// MarkStale flags the key's cached entry as stale — the external-writer
// signal: the next strict read misses and queues a refetch, while
// accept-stale reads keep serving the old value until it lands.
func (inst *JobCache[W]) MarkStale(key string) {
	inst.cache.MarkAsStale(key)
}

// MarkStaleIfOlder is the version-carrying external-writer signal:
// it stales the cached entry only if its Order is below order, so a
// redundant signal for a version the view already holds is free —
// the natural sink for an invalidation stream carrying (key, Order).
func (inst *JobCache[W]) MarkStaleIfOlder(key string, order time.Time) {
	inst.cache.MarkAsStaleIfOlder(key, order.UnixNano())
}

// Invalidate drops the key's cached entry (L1 and stash).
func (inst *JobCache[W]) Invalidate(key string) {
	inst.cache.Delete(key)
}

// InvalidateAll drops every cached entry — the bulk external-writer
// signal (e.g. after an import). In-flight miss bookkeeping (queued
// keys, pending work items) and the dirty-window pins are dropped
// with it: call between frames, with no suspended work and no
// unflushed local writes (the fetcher's dirty-guard keeps pre-write
// rows out of the cleared cache until the next Flush, at the cost of
// misses on those keys).
func (inst *JobCache[W]) InvalidateAll() {
	inst.cache.Clear()
}

// fetchLatestSQL is the batched newest-row-per-key point lookup shared
// by the cache fetcher and GetFetch.
func (inst *JobStore) fetchLatestSQL(keys []string) string {
	var sb strings.Builder
	sb.WriteString("SELECT * FROM ")
	sb.WriteString(inst.tableName())
	sb.WriteString(" WHERE " + JobColKey + " IN (")
	for i, k := range keys {
		if i > 0 {
			sb.WriteByte(',')
		}
		sb.WriteString(watchbillKeyLiteral(k))
	}
	sb.WriteString(") ORDER BY " + JobColOrder + " DESC LIMIT 1 BY " + JobColKey)
	sb.WriteString(watchbillArrowOutputSettings)
	return sb.String()
}

// watchbillFetcher implements caching.ItemFetcherI for attached cache views —
// an unexported shim so the fetch plumbing stays off the store's
// public method set.
type watchbillFetcher struct{ st *JobStore }

var _ caching.ItemFetcherI[string, *JobEntity] = (*watchbillFetcher)(nil)

// DeterminePartition implements caching.ItemFetcherI. Single partition
// in v1 (one table, one server).
func (inst *watchbillFetcher) DeterminePartition(key string) uint64 { return 0 }

// FetchItemSinglePartition implements caching.ItemFetcherI: one batched
// point lookup per fetch. Duplicate versions collapse newest-first.
// Dirty keys (written locally, not yet flushed) are fetched but not
// cached. With write-through the version gate already rejects the
// pre-write row while the newer entry is resident; this guard is the
// remaining defense for dirty keys the views could NOT materialize
// (Raw commits, discarded writes) and for InvalidateAll inside a
// dirty window, where the cache is cold and the gate has nothing to
// compare against.
func (inst *watchbillFetcher) FetchItemSinglePartition(ctx context.Context, partition uint64, keys []string, target caching.ItemTargetI[string, *JobEntity]) (err error) {
	ents, err := inst.st.queryEntities(ctx, inst.st.fetchLatestSQL(keys))
	if err != nil {
		return
	}
	for _, ent := range ents {
		if _, d := inst.st.dirty[ent.ID]; d {
			continue
		}
		target.AddItem(ent.ID, ent)
	}
	return
}

// Baked ADR-0066 Filter artefacts: rows carrying a conforming
// component. Generated from Plan ⋈ IR; membership ids are literals.
const (
	watchbillScanJobFilter = "has(\"tv:jobKind:lr:lr:u64:1247:::0::data\", 9223372049739677770) AND has(\"tv:jobSubject:lr:lr:u64:1247:::0::data\", 9223372049739677771) AND has(\"tv:jobQueue:lr:lr:u64:1247:::0::data\", 9223372049739677772) AND has(\"tv:jobPriority:lr:lr:u64:1247:::0::data\", 9223372049739677773) AND has(\"tv:jobMaxAttempts:lr:lr:u64:1247:::0::data\", 9223372049739677774) AND has(\"tv:jobBackoff:lr:lr:u64:1247:::0::data\", 9223372049739677775) AND has(\"tv:jobBackoffBaseMs:lr:lr:u64:1247:::0::data\", 9223372049739677776) AND has(\"tv:jobTimeoutMs:lr:lr:u64:1247:::0::data\", 9223372049739677777) AND has(\"tv:jobOwnerApp:lr:lr:u64:1247:::0::data\", 9223372049739677701) AND has(\"tv:jobRequesterRun:lr:lr:u64:1247:::0::data\", 9223372049739677716) AND has(\"tv:jobArgsKind:lr:lr:u64:1247:::0::data\", 9223372049739677778) AND has(\"tv:jobArgs:lr:lr:u64:1247:::0::data\", 9223372049739677779) AND has(\"tv:jobState:lr:lr:u64:1247:::0::data\", 9223372049739677780) AND has(\"tv:jobAttempt:lr:lr:u64:1247:::0::data\", 9223372049739677781) AND has(\"tv:jobRunAfter:lr:lr:u64:1247:::0::data\", 9223372049739677782) AND has(\"tv:jobWorkerRun:lr:lr:u64:1247:::0::data\", 9223372049739677783) AND has(\"tv:jobFinishedAt:lr:lr:u64:1247:::0::data\", 9223372049739677784) AND has(\"tv:jobLastError:lr:lr:u64:1247:::0::data\", 9223372049739677785) AND countEqual(\"tv:jobKind:lr:lr:u64:1247:::0::data\", 9223372049739677770) = 1 AND countEqual(\"tv:jobSubject:lr:lr:u64:1247:::0::data\", 9223372049739677771) = 1 AND countEqual(\"tv:jobQueue:lr:lr:u64:1247:::0::data\", 9223372049739677772) = 1 AND countEqual(\"tv:jobPriority:lr:lr:u64:1247:::0::data\", 9223372049739677773) = 1 AND countEqual(\"tv:jobMaxAttempts:lr:lr:u64:1247:::0::data\", 9223372049739677774) = 1 AND countEqual(\"tv:jobBackoff:lr:lr:u64:1247:::0::data\", 9223372049739677775) = 1 AND countEqual(\"tv:jobBackoffBaseMs:lr:lr:u64:1247:::0::data\", 9223372049739677776) = 1 AND countEqual(\"tv:jobTimeoutMs:lr:lr:u64:1247:::0::data\", 9223372049739677777) = 1 AND countEqual(\"tv:jobOwnerApp:lr:lr:u64:1247:::0::data\", 9223372049739677701) = 1 AND countEqual(\"tv:jobRequesterRun:lr:lr:u64:1247:::0::data\", 9223372049739677716) = 1 AND countEqual(\"tv:jobArgsKind:lr:lr:u64:1247:::0::data\", 9223372049739677778) = 1 AND countEqual(\"tv:jobArgs:lr:lr:u64:1247:::0::data\", 9223372049739677779) = 1 AND countEqual(\"tv:jobState:lr:lr:u64:1247:::0::data\", 9223372049739677780) = 1 AND countEqual(\"tv:jobAttempt:lr:lr:u64:1247:::0::data\", 9223372049739677781) = 1 AND countEqual(\"tv:jobRunAfter:lr:lr:u64:1247:::0::data\", 9223372049739677782) = 1 AND countEqual(\"tv:jobWorkerRun:lr:lr:u64:1247:::0::data\", 9223372049739677783) = 1 AND countEqual(\"tv:jobFinishedAt:lr:lr:u64:1247:::0::data\", 9223372049739677784) = 1 AND countEqual(\"tv:jobLastError:lr:lr:u64:1247:::0::data\", 9223372049739677785) = 1"
)

// ScanJob iterates the entities whose rows carry a conforming Job
// component, ordered by (Order, Key) — so entities sharing an Order
// still come out in a fixed sequence. Rows that tie on BOTH (the same
// key written twice at the same Order) are not ordered against each
// other by this clause; the table keeps newest-per-key, so which of
// them survives is the engine's choice, not the scan's.
// opts.ExtraPredicate (trusted raw SQL over the physical columns —
// never untrusted input) further restricts the scan; opts.Limit
// caps the row count. The Filter artefact uses ClickHouse
// built-ins only, so this is a single SELECT — no helper UDFs, no
// multi-statement script (the ExecutorI contract). The sequence is
// single-use; ctx must stay valid until iteration completes; an
// error ends it as a final (nil, err) pair. Scans see only flushed
// rows.
func (inst *JobStore) ScanJob(ctx context.Context, opts recordstore.ScanOpts) iter.Seq2[*JobEntity, error] {
	where := watchbillScanJobFilter
	if opts.ExtraPredicate != "" {
		where = "(" + where + ") AND (" + opts.ExtraPredicate + ")"
	}
	sql := "SELECT * FROM " + inst.tableName() +
		" WHERE " + where +
		" ORDER BY " + JobColOrder + " ASC, " + JobColKey + " ASC"
	if opts.Limit > 0 {
		sql += " LIMIT " + strconv.Itoa(opts.Limit)
	}
	sql += watchbillArrowOutputSettings
	return inst.iterateEntities(ctx, sql)
}

// Latest returns the newest row for key, tombstone-blind (the raw
// row-level primitive — a deleted key still returns its tombstone
// row; GetLive is the interpreted state-view read). Reads see only
// flushed rows.
func (inst *JobStore) Latest(ctx context.Context, key string) (ent *JobEntity, found bool, err error) {
	sql := "SELECT * FROM " + inst.tableName() +
		" WHERE " + JobColKey + " = " + watchbillKeyLiteral(key) +
		" ORDER BY " + JobColOrder + " DESC LIMIT 1" + watchbillArrowOutputSettings
	ents, err := inst.queryEntities(ctx, sql)
	if err != nil || len(ents) == 0 {
		return
	}
	ent = ents[0]
	found = true
	return
}

// Replay iterates the rows for key with the order column >= fromOrder
// in ascending order — the event-replay primitive. A zero fromOrder
// replays everything (zero time.Time has no defined UnixNano;
// recordstore.SeqTs(0) is the equivalent explicit bound);
// opts.To bounds the replay exclusively ("state as of To") and
// opts.Limit caps the row count. The sequence is single-use; ctx
// must stay valid until iteration completes; the query may execute
// at call time or lazily during iteration (buffered in v1 — a
// streaming executor changes nothing visible); an error ends the
// sequence as a final (nil, err) pair. Reads see only flushed rows.
func (inst *JobStore) Replay(ctx context.Context, key string, fromOrder time.Time, opts recordstore.ReplayOpts) iter.Seq2[*JobEntity, error] {
	sql := "SELECT * FROM " + inst.tableName() +
		" WHERE " + JobColKey + " = " + watchbillKeyLiteral(key)
	if !fromOrder.IsZero() {
		sql += " AND " + JobColOrder + " >= fromUnixTimestamp64Nano(" + strconv.FormatInt(fromOrder.UnixNano(), 10) + ")"
	}
	if !opts.To.IsZero() {
		sql += " AND " + JobColOrder + " < fromUnixTimestamp64Nano(" + strconv.FormatInt(opts.To.UnixNano(), 10) + ")"
	}
	sql += " ORDER BY " + JobColOrder + " ASC"
	if opts.Limit > 0 {
		sql += " LIMIT " + strconv.Itoa(opts.Limit)
	}
	sql += watchbillArrowOutputSettings
	return inst.iterateEntities(ctx, sql)
}

// JobComponentSQL publishes this store's ADR-0066 read-back artefacts —
// the SQL its component definitions generate — for an authoring surface
// to expand (ADR-0189). A host registers it into a componentsql.Registry;
// nothing here self-registers.
//
// Filter is the same constant the Scan verbs use, so the store's own read
// path and the authoring surface cannot disagree about what a conforming
// row is. Projection must not be embedded without Filter — it locates an
// attribute by indexOf and returns the first match, so on a row carrying a
// membership twice it answers plausibly and wrongly (ADR-0066).
