// --- decode (Arrow → entity bags). ---

// watchbillSectionReaderI is the uniform slice of the generated read-access
// readers. Column indices stay at their constructor defaults — the
// schema order a SELECT * returns.
type watchbillSectionReaderI interface {
	LoadFromRecord(raruntime.RecordI) error
	Release()
}

func (inst *JobStore) queryEntities(ctx context.Context, sql string) (ents []*JobEntity, err error) {
	for rec, rerr := range inst.exec.QueryArrow(ctx, sql) {
		if rerr != nil {
			err = eh.Errorf("query entities: %w", rerr)
			return
		}
		batch, derr := decodeJobRecord(rec)
		rec.Release()
		if derr != nil {
			err = derr
			return
		}
		ents = append(ents, batch...)
	}
	return
}

// iterateEntities adapts the buffered query path to the single-use
// iterator contract shared by Replay and the Scan verbs: entities
// yield in query order; an error yields once as (nil, err) and ends
// the sequence.
func (inst *JobStore) iterateEntities(ctx context.Context, sql string) iter.Seq2[*JobEntity, error] {
	return func(yield func(*JobEntity, error) bool) {
		ents, err := inst.queryEntities(ctx, sql)
		if err != nil {
			yield(nil, err)
			return
		}
		for _, ent := range ents {
			if !yield(ent, nil) {
				return
			}
		}
	}
}

// decodeJobRecord reads one fetched Arrow record into entity bags:
// envelope from the plain readers, components via presence-gated,
// membership-matched reads (fat rows carry optional components — the
// kind-homogeneous helpers cannot decode them).
func decodeJobRecord(rec arrow.RecordBatch) (ents []*JobEntity, err error) {
	idR := lowlevel.NewReadAccessWatchbillTablePlainEntityIdAttributes()
	tsR := lowlevel.NewReadAccessWatchbillTablePlainEntityTimestampAttributes()
	jobKindR := lowlevel.NewReadAccessWatchbillTableTaggedJobKind()
	jobSubjectR := lowlevel.NewReadAccessWatchbillTableTaggedJobSubject()
	jobQueueR := lowlevel.NewReadAccessWatchbillTableTaggedJobQueue()
	jobPriorityR := lowlevel.NewReadAccessWatchbillTableTaggedJobPriority()
	jobMaxAttemptsR := lowlevel.NewReadAccessWatchbillTableTaggedJobMaxAttempts()
	jobBackoffR := lowlevel.NewReadAccessWatchbillTableTaggedJobBackoff()
	jobBackoffBaseMsR := lowlevel.NewReadAccessWatchbillTableTaggedJobBackoffBaseMs()
	jobTimeoutMsR := lowlevel.NewReadAccessWatchbillTableTaggedJobTimeoutMs()
	jobOwnerAppR := lowlevel.NewReadAccessWatchbillTableTaggedJobOwnerApp()
	jobRequesterRunR := lowlevel.NewReadAccessWatchbillTableTaggedJobRequesterRun()
	jobArgsKindR := lowlevel.NewReadAccessWatchbillTableTaggedJobArgsKind()
	jobArgsR := lowlevel.NewReadAccessWatchbillTableTaggedJobArgs()
	jobStateR := lowlevel.NewReadAccessWatchbillTableTaggedJobState()
	jobAttemptR := lowlevel.NewReadAccessWatchbillTableTaggedJobAttempt()
	jobRunAfterR := lowlevel.NewReadAccessWatchbillTableTaggedJobRunAfter()
	jobWorkerRunR := lowlevel.NewReadAccessWatchbillTableTaggedJobWorkerRun()
	jobFinishedAtR := lowlevel.NewReadAccessWatchbillTableTaggedJobFinishedAt()
	jobLastErrorR := lowlevel.NewReadAccessWatchbillTableTaggedJobLastError()
	readers := []watchbillSectionReaderI{idR, tsR, jobKindR, jobSubjectR, jobQueueR, jobPriorityR, jobMaxAttemptsR, jobBackoffR, jobBackoffBaseMsR, jobTimeoutMsR, jobOwnerAppR, jobRequesterRunR, jobArgsKindR, jobArgsR, jobStateR, jobAttemptR, jobRunAfterR, jobWorkerRunR, jobFinishedAtR, jobLastErrorR}
	for _, r := range readers {
		err = r.LoadFromRecord(rec)
		if err != nil {
			err = eh.Errorf("load watchbill reader from record: %w", err)
			return
		}
	}
	defer func() {
		for _, r := range readers {
			r.Release()
		}
	}()

	n := idR.ValueId.Len()
	tsType, ok := tsR.ValueTs.DataType().(*arrow.TimestampType)
	if !ok {
		err = eh.Errorf("order column is not a timestamp (got %s)", tsR.ValueTs.DataType())
		return
	}
	ents = make([]*JobEntity, 0, n)
	for i := range n {
		ent := &JobEntity{
			ID: idR.ValueId.Value(i),
			Ts: tsR.ValueTs.Value(i).ToTime(tsType.Unit).UTC(),
		}
		{
			row, ok, e := jobReadRow(i, jobKindR.GetAttributes(), jobKindR.GetMemberships(), jobSubjectR.GetAttributes(), jobSubjectR.GetMemberships(), jobQueueR.GetAttributes(), jobQueueR.GetMemberships(), jobPriorityR.GetAttributes(), jobPriorityR.GetMemberships(), jobMaxAttemptsR.GetAttributes(), jobMaxAttemptsR.GetMemberships(), jobBackoffR.GetAttributes(), jobBackoffR.GetMemberships(), jobBackoffBaseMsR.GetAttributes(), jobBackoffBaseMsR.GetMemberships(), jobTimeoutMsR.GetAttributes(), jobTimeoutMsR.GetMemberships(), jobOwnerAppR.GetAttributes(), jobOwnerAppR.GetMemberships(), jobRequesterRunR.GetAttributes(), jobRequesterRunR.GetMemberships(), jobArgsKindR.GetAttributes(), jobArgsKindR.GetMemberships(), jobArgsR.GetAttributes(), jobArgsR.GetMemberships(), jobStateR.GetAttributes(), jobStateR.GetMemberships(), jobAttemptR.GetAttributes(), jobAttemptR.GetMemberships(), jobRunAfterR.GetAttributes(), jobRunAfterR.GetMemberships(), jobWorkerRunR.GetAttributes(), jobWorkerRunR.GetMemberships(), jobFinishedAtR.GetAttributes(), jobFinishedAtR.GetMemberships(), jobLastErrorR.GetAttributes(), jobLastErrorR.GetMemberships())
			if e != nil {
				err = eh.Errorf("read job component: %w", e)
				return
			}
			if ok {
				row.ID = ent.ID
				ent.Job = option.Some(row)
			}
		}
		ents = append(ents, ent)
	}
	return
}
